/**
 * Booking.com Demand API client (owner 10 Nov: "booking.com ka demand api generate kro").
 *
 * FACTS, from Booking.com's own developer portal (read 10 Nov):
 *  - the Demand API is not self-serve. Access is for MANAGED AFFILIATE PARTNERS: you apply, Booking.com
 *    approves the business, and only then issues an authentication token. There is no signup form that
 *    mints a key, so no account can be "created" with an email/password and no key can be generated by us.
 *  - their docs also list a METASEARCH CONNECT API, which is the product that matches this site exactly
 *    (search on our side, book on Booking.com) and is the better fit to apply for.
 *  - authentication: an affiliate id header (X-Affiliate-Id) plus a token.
 *
 * So this module is the wiring, not a fake: the moment an approved affiliate id + token exist the hotel
 * source below starts returning real priced rows with zero code change, and until then it raises
 * NOT_CONFIGURED instead of pretending. No price is ever invented; rows without a positive price are
 * dropped (owner's No Price, No Card rule).
 */

export interface BookingDemandConfig {
  affiliateId: string;
  token: string;
  base: string;
}

export function bookingDemandConfig(): BookingDemandConfig | null {
  const affiliateId = (process.env.BOOKING_DEMAND_AFFILIATE_ID || '').trim();
  const token = (process.env.BOOKING_DEMAND_TOKEN || '').trim();
  if (!affiliateId || !token) return null;
  const base = (process.env.BOOKING_DEMAND_API_BASE || 'https://demandapi.booking.com/3.3').trim().replace(/\/$/, '');
  return { affiliateId, token, base };
}

export function bookingDemandConfigured(): boolean {
  return bookingDemandConfig() !== null;
}

/** Query the accommodations search endpoint. Throws on transport errors so the health ladder sees them. */
export async function bookingDemandSearch(
  body: Record<string, unknown>,
  fetchImpl: typeof fetch = fetch,
): Promise<any> {
  const cfg = bookingDemandConfig();
  if (!cfg) throw new Error('BOOKING_DEMAND_NOT_CONFIGURED');
  const res = await fetchImpl(`${cfg.base}/accommodations/search`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Accept: 'application/json',
      'X-Affiliate-Id': cfg.affiliateId,
      Authorization: `Bearer ${cfg.token}`,
    },
    body: JSON.stringify(body),
  });
  if (!res.ok) throw new Error(`booking demand HTTP ${res.status}`);
  return res.json();
}

/**
 * Extracts sellable rows from a Demand API search response. Shape-tolerant on purpose: the exact field
 * names differ per version, so we read the common ones and DROP anything without a positive price.
 */
export function bookingDemandItems(payload: any, opts: { sourceId?: string; checkin?: string; checkout?: string; city?: string } = {}): any[] {
  const list = payload?.data?.accommodations
    || payload?.data?.result
    || payload?.accommodations
    || payload?.result
    || [];
  if (!Array.isArray(list)) return [];
  const out: any[] = [];
  for (const raw of list) {
    const price = Number(
      raw?.price?.book?.amount
      ?? raw?.price?.display?.amount
      ?? raw?.price?.total
      ?? raw?.price
      ?? raw?.booking?.price
      ?? 0,
    );
    if (!Number.isFinite(price) || price <= 0) continue; // No Price, No Card
    const name = String(raw?.name || raw?.accommodation?.name || raw?.property?.name || '').trim();
    if (!name) continue;
    const url = String(raw?.url || raw?.deeplink || raw?.accommodation?.url || '').trim();
    out.push({
      title: name,
      provider: 'Booking.com',
      price,
      currency: String(raw?.price?.book?.currency || raw?.price?.currency || 'INR'),
      url,
      checkin: opts.checkin,
      checkout: opts.checkout,
      city: opts.city,
      sourceId: opts.sourceId || 'w_hotels_booking_demand',
      rawId: raw?.id || raw?.accommodation?.id || null,
    });
  }
  return out;
}
